class Animal:
    def __init__(self, name, sound):
        self.name = name
        self.sound = sound

    def speak(self):
        return f'{self.name} says {self.sound}!'

    def __str__(self):
        return f'{type(self).__name__}({self.name})'


# Inherit from Animal
class Dog(Animal):
    def __init__(self, name):
        super().__init__(name, 'Woof')   # call parent __init__

    def fetch(self, item):
        return f'{self.name} fetched the {item}!'


class Cat(Animal):
    def __init__(self, name):
        super().__init__(name, 'Meow')

    def speak(self):   # override parent method
        return f'{self.name} says {self.sound}... maybe.'


dog = Dog('Rex')
cat = Cat('Whiskers')

print(dog.speak())    # Rex says Woof!
print(cat.speak())    # Whiskers says Meow... maybe.
print(dog.fetch('ball'))   # Rex fetched the ball!
print(isinstance(dog, Animal))  # True — Dog IS an Animal

# @property — computed attribute
class Temperature:
    def __init__(self, celsius):
        self._celsius = celsius

    @property
    def celsius(self):
        return self._celsius

    @celsius.setter
    def celsius(self, value):
        if value < -273.15:
            raise ValueError('Below absolute zero!')
        self._celsius = value

    @property
    def fahrenheit(self):          # read-only computed property
        return self._celsius * 9/5 + 32


t = Temperature(100)
print(t.fahrenheit)  # 212.0
t.celsius = 0        # uses setter
print(t.fahrenheit)  # 32.0


# @dataclass — auto-generates __init__, __repr__, __eq__
from dataclasses import dataclass, field

@dataclass
class Point:
    x: float
    y: float
    label: str = ''                     # optional with default

    def distance_to_origin(self) -> float:
        return (self.x**2 + self.y**2) ** 0.5


p = Point(3, 4)
print(p)                        # Point(x=3, y=4, label='')
print(p.distance_to_origin())   # 5.0
print(p == Point(3, 4))         # True — auto __eq__
